// Writes two small generated files so the server also works where it cannot list folders at run time (serverless hosts
// bundle only what the code visibly requires):
//   server/registry.js  - one static require() per game in server/games/
//   server/models.json  - the .glb files in public/models/
// Runs automatically before `npm start` and as the hosting build step. Run it by hand after adding a game or a model
// if you start the server some other way:  node server/build-manifest.js
const fs = require('fs'), path = require('path');
const games = fs.readdirSync(path.join(__dirname, 'games')).filter((f) => f.endsWith('.js')).sort();
fs.writeFileSync(path.join(__dirname, 'registry.js'), '// GENERATED by server/build-manifest.js. Do not edit.\nmodule.exports = [\n' + games.map((f) => `  require('./games/${f}'),`).join('\n') + '\n];\n');
let models = []; try { models = fs.readdirSync(path.join(__dirname, '../public/models')).filter((f) => /\.(glb|gltf)$/i.test(f)).sort(); } catch (e) { /* none yet */ }
fs.writeFileSync(path.join(__dirname, 'models.json'), JSON.stringify(models, null, 0) + '\n');
console.log(`manifest: ${games.length} games, ${models.length} models`);
